#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <string>
#include "cJSON.h"
#include "lodepng.h"

static std::vector<float> getMat(cJSON* root, const char* key) {
    cJSON* node = cJSON_GetObjectItemCaseSensitive(root, key);
    std::vector<float> out;
    if (!node) return out;
    // node is array; may be nested (2D) or flat (1D)
    cJSON* row = NULL;
    cJSON_ArrayForEach(row, node) {
        if (cJSON_IsArray(row)) {
            cJSON* v = NULL;
            cJSON_ArrayForEach(v, row) out.push_back((float)v->valuedouble);
        } else {
            out.push_back((float)row->valuedouble);
        }
    }
    return out;
}

// y = W x + b ; W is [out x in] row-major, x is [in]
static std::vector<float> linear(const std::vector<float>& W,
                                 const std::vector<float>& b,
                                 const std::vector<float>& x,
                                 int in, int out) {
    std::vector<float> y(out, 0.0f);
    for (int o = 0; o < out; ++o) {
        float acc = b[o];
        const float* wr = &W[(size_t)o * in];
        for (int i = 0; i < in; ++i) acc += wr[i] * x[i];
        y[o] = acc;
    }
    return y;
}

static void relu(std::vector<float>& v) {
    for (auto& e : v) if (e < 0) e = 0;
}

int main(int argc, char** argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }
    // read weights json
    FILE* f = fopen(argv[1], "rb");
    if (!f) { fprintf(stderr, "cannot open weights\n"); return 1; }
    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);
    std::string buf; buf.resize(sz);
    if (fread(&buf[0], 1, sz, f) != (size_t)sz) { fclose(f); return 1; }
    fclose(f);
    cJSON* root = cJSON_Parse(buf.c_str());
    if (!root) { fprintf(stderr, "bad json\n"); return 1; }

    std::vector<float> iw = getMat(root, "input_layer.weight");
    std::vector<float> ib = getMat(root, "input_layer.bias");
    std::vector<float> hw = getMat(root, "hidden_layer.weight");
    std::vector<float> hb = getMat(root, "hidden_layer.bias");
    std::vector<float> ow = getMat(root, "output_layer.weight");
    std::vector<float> ob = getMat(root, "output_layer.bias");

    int hidden = (int)ib.size();
    int input = hidden ? (int)(iw.size() / hidden) : 0;
    int classes = (int)ob.size();

    // load image
    std::vector<unsigned char> img;
    unsigned w, h;
    unsigned err = lodepng::decode(img, w, h, argv[2], LCT_GREY, 8);
    if (err) { fprintf(stderr, "png error %u\n", err); cJSON_Delete(root); return 1; }

    std::vector<float> x((size_t)w * h);
    for (size_t i = 0; i < x.size(); ++i) x[i] = img[i] / 255.0f;
    if ((int)x.size() != input) {
        // pad/truncate defensively
        x.resize(input, 0.0f);
    }

    std::vector<float> a = linear(iw, ib, x, input, hidden); relu(a);
    std::vector<float> b2 = linear(hw, hb, a, hidden, hidden); relu(b2);
    std::vector<float> o = linear(ow, ob, b2, hidden, classes);

    int best = 0; float bv = o[0];
    for (int i = 1; i < classes; ++i) if (o[i] > bv) { bv = o[i]; best = i; }

    printf("%d\n", best);
    cJSON_Delete(root);
    return 0;
}

